"""First independent B source judgments, manually reasoned by physical group.

This writes only this reviewer's own review artifacts. It never edits inputs.
Primary full texts in primary-text/ and primary-cache/ are working caches.
"""
import collections, datetime, hashlib, json, pathlib, sys
from read_group import GROUPS, GOALS, PROFILES, ANCHORS, CELLS, BASE

OUT = pathlib.Path(__file__).parent
SOURCE = {}
def S(i, jurisdictions, decision, reason, primary=None, pages=None, course=None, anchors=None, qualification=None):
    for jurisdiction in jurisdictions.split():
        key=(i,'DE-'+jurisdiction)
        assert key not in SOURCE,key
        SOURCE[key]={'decision':decision,'sourceScientificReasonDe':reason,
                     'primaryPrefix':primary,'actualPDFPages':pages or [],
                     'originalCourseStageProgram':course,
                     'witnessAnchorIds':(anchors or {}).get(jurisdiction,[]),
                     'scopeQualificationDe':qualification}

EP='Einführungsphase, Wahlpflicht-Themenfeld, ohne GK/LK-Trennung; kein Beleg einer individuellen Wahl'
COMMON='Gymnasiale Oberstufe, grundlegendes und erhöhtes Anforderungsniveau'

S(1,'BB BE','approve','Das Original behandelt Biodieselgewinnung im Zusammenhang mit Kraftstoffen und nachhaltigem Wirtschaften. Das aktuelle Biodiesel-Profil verlangt ausdrücklich die Einordnung von Pflanzenölen nach Struktur, Verwendung und Umweltfolgen; diese Sachkompetenz wird in seinen eigenen Vergleichs- und Begründungsschritten gebraucht.', '2fa91c',[17,23],EP,
  qualification='Nur Erwerbsunterstützung für das tatsächlich aufgenommene Wahlpflicht-Thema. Keine allgemeine offizielle Biodieselpflicht und keine Feststellung einer Themenwahl.')
S(2,'BB BE','hold','Die erste Faraday-Beziehung ist für die quantitativen Elektrolyseaufgaben notwendig. Im Original steht die Faraday-Gleichung jedoch in der zusätzlichen LK-Spalte. Ein bloßer GK/LK-Zielstatus des aktuellen Vorziels überträgt diese LK-Quelle nicht auf den GK. Ein tatsächlich entsprechender GK-Nachweis oder eine kursgenaue Begrenzung fehlt.', '2fa91c',[53],'Qualifikationsphase: Faraday nur zusätzlich LK')
S(2,'NI','hold','Das Original ordnet sowohl das erste Faraday-Gesetz als auch dessen quantitative Anwendung dem erhöhten Anforderungsniveau zu. Die physikalisch richtige Vorleistung liefert damit keinen Grundkurs-Quellenersatz für die derzeit breite Paarzeile.', 'bd082d',[26],'Qualifikationsphase: Faraday eA/LK')
S(7,'BW','approve','Für die auf der Originalseite verlangte experimentelle Konzentrationsbestimmung mittels Säure-Base-Titration ist der sichere Umgang mit Glasgeräten, Chemikalien und Schutzmaßnahmen eine tatsächliche Ausführungsbedingung. Verwendet wird der passende Sek-I-Anker; die zuerst gewählte Leistungsfach-Titrationsseite ist dafür nicht erforderlich.', '3ae66c',[23],'Klassen 9/10/11, gemeinsamer Sek-I-Standard',{'BW':['anchor-c649bced74ea4657ffc8']})
S(7,'BB BE','approve','Die Originaltabelle verlangt die Durchführung einer Säure-Base-Titration im gemeinsamen Grund-/Leistungskursbereich. Das aktuelle abhängige Profil verlangt tatsächliche Bedienung und Durchführung; die allgemeine Schutz- und Sicherheitskompetenz ist hierfür erforderlich und wird nicht durch ein ausgefülltes Musterprotokoll ersetzt.', '2fa91c',[45],'Qualifikationsphase: gemeinsamer GK/LK-Bereich; tatsächliche Durchführung')
S(7,'NI','approve','Der konkrete Quellenanker zur Konzentrationsbestimmung durch Säure-Base-Titration trägt das aktuelle praktische Titrationsziel besser als die mechanisch gewählte Indikatorfunktion. Bei der verlangten realen Durchführung sind die vorgelagerten Labor-Sicherheitsregeln erforderlich.', 'bd082d',[21],COMMON,{'NI':['anchor-b0270460cc3fe7a7a24e']})
S(11,'NW','approve','Beide Originalkursabschnitte verlangen die experimentelle Konzentrationsbestimmung durch Säure-Base-Titration samt Berechnungen. Das aktuelle Profil verlangt n=cV, stöchiometrischen Reaktionsfaktor und Aliquotkorrektur; dazu muss n als Teilchenzahlmaß und nicht als Masse oder Volumen verstanden werden. GK und LK werden mit eigenen Originalankern belegt.', '24af8d',[39,48],'Qualifikationsphase: GK S.39 und LK S.48',{'NW':['anchor-4abdbe9913c8ff4f91cf','anchor-8d5d5ec3622249b267ed']})
S(11,'SH','approve','Die gemeinsame Originalspalte nennt die quantitative Konzentrationsbestimmung durch Titration. Gerade deren c-V-Reaktionsfaktor-Auswertung im aktuellen Profil benötigt die Stoffmenge als Teilchenzahlmaß. Der LK-Zusatz zu detaillierten Titrationskurven wird dafür nicht auf den GK übertragen.', 'ab56f1',[65],COMMON,{'SH':['anchor-53a80a1ad8b1903b3d23']})
S(11,'HH','approve','Die gemeinsame Studienstufenspalte verlangt die Konzentrationsbestimmung und Auswertung von Säure-Base-Titrationen. Für die eigenen Äquivalenz- und Aliquotrechnungen des aktuellen Profils ist der Stoffmengenbegriff erforderlich; die zusätzliche LK-Kurvenberechnung wird nicht als GK-Beweis benutzt.', '4f452d',[30],'Studienstufe, gemeinsamer grundlegender/erhöhter Bereich',{'HH':['anchor-525dfbf432e59eee281b']})
S(11,'MV','approve','Die Originalseite verlangt Konzentrationsberechnungen und ein Schülerexperiment zur Säure-Base-Titration im gemeinsamen Teil. Die aktuellen Zahlenaufgaben rechnen Reaktionsstoffmengen aus c und V; n als Teilchenzahlmaß ist dafür unverzichtbar. Die gedruckte S.24 ist PDF-S.28.', 'dcc123',[28],'Qualifikationsphase, gemeinsamer GK/LK-Teil',{'MV':['anchor-cb6ed473a45ed4009c49']})
S(11,'RP','approve','Im Original steht die einprotonige Säure-Base-Titration im Fundamentum für Grund- und Leistungsfach. Das löst die falsche LK-Einschränkung und den unpassenden Seitenverweis der extrahierten Zelle inhaltlich auf. Die aktuelle quantitative Äquivalenzauswertung braucht n als Teilchenzahlmaß.', '8d701a',[34],'MSS Analytik: Grund- und Leistungsfach/Fundamentum, nicht nur LK',{'RP':['anchor-ab4ea32b0178e1a4e837']},'Originalbefund berichtigt die Interpretation der Rohmetadaten; keine Quelldatei oder Mappingzeile wurde geändert.')
S(11,'SL','hold','Die vorhandenen exakten Saarland-Originalpartner sind Klasse 8 und Einführungsphase NW. Für den ausgewählten oberen GK-/LK-Titrationsbeleg fehlt hier das passende Original samt Kurs- und Seitenkontext. Eine sichere Stoffmengen-Abhängigkeit ersetzt diesen Primärnachweis nicht.')
S(11,'ST','approve','Die Originalabschnitte verlangen in gAN und eAN quantitative Säure-Base-Titration; die jeweilige Kursseite wurde gesondert gelesen. Die aktuellen Konzentrations-, Äquivalenz- und Aliquotaufgaben sind ohne Bedeutung der Stoffmenge als Zahl reagierender Teilchen nicht bearbeitbar.', 'fcdbb0',[40,49],'11/12 gAN S.40 und eAN S.49',{'ST':['anchor-750a850b746ecff911a7','anchor-3b9b17522438e4ec3a74']})
S(11,'TH','approve','Die gemeinsame linke Originalspalte verlangt Konzentrationsbestimmungen sehr starker Säuren/Basen durch Schülerexperiment. Die aktuellen Titrationsaufgaben brauchen das Verhältnis der Teilchenstoffmengen und die Umrechnung aus cV; die rechte Zusatzspalte für eA wird nicht verallgemeinert.', 'f89768',[51],COMMON)
S(12,'BW','approve','Das Original fordert das universelle molare Volumen unter gleichen Bedingungen. Das aktuelle abhängige Profil muss erklären, warum sich ein gemeinsames Volumen auf gleiche Stoffmengen verschiedener Gase bezieht. Genau dies ist der Inhalt des Avogadro-Vorwissens, ohne eine zusätzliche kinetische Herleitung zu verlangen.', '3ae66c',[23],'Klassen 9/10/11, gemeinsamer Sek-I-Standard')
S(12,'BB BE','approve','Im Original der Einführungsphase werden Stoffmenge, Gasvolumen und molare Größen verknüpft. Im aktuellen Profil ist nicht nur Einsetzen gefragt: Es begründet die Gas-Unabhängigkeit des molaren Volumens bei gleichem T,p. Dafür ist der Avogadro-Zusammenhang notwendig.', '2fa91c',[17,18],EP,qualification='Einführungsphasen-Themenangebot bleibt Wahlpflicht; keine universelle offizielle Themenpflicht.')
S(13,'BB BE','hold','Das Original nennt im gemeinsamen Kursteil Lokalelemente. Es belegt damit einen Korrosionskontext, aber nicht die volle aktuelle Abhängigkeit mit ausgeglichenen Teilgleichungen in saurem und neutralem Milieu. Ein Themenwort darf diese zusätzliche Operationsbreite nicht stillschweigend tragen.', '2fa91c',[53],'Qualifikationsphase: Lokalelement gemeinsam GK/LK')
S(13,'NW','approve','Der GK-Originaltext verlangt die Lokalelementbildung ausdrücklich auch mittels Reaktionsgleichungen; der LK behandelt Säure-/Sauerstoffkorrosion und experimentell geprüfte Lokalelemente. Das vollständige aktuelle Korrosionsprofil verwendet diese Teilreaktionen im sauren und neutralen Milieu. Die dafür nötige Gleichungsbilanz ist sachlich, nicht nur thematisch, begründet.', '24af8d',[41,50,51],'Qualifikationsphase GK und LK, getrennte Originalabschnitte',{'NW':['anchor-941b4f8b94cd4dee4abc','anchor-7319011707210c6dd3e3']})
S(13,'SH','hold','Die gemeinsame Originalseite nennt Metallkorrosion und Schutz. Für den angebotenen Quellenersatz fehlt jedoch ein konkreter Originaloperator, der die volle aktuelle Bilanzierung saurer und neutraler wässriger Redoxsysteme zur erforderlichen Vorleistung macht. Das allgemeinere Korrosionsthema reicht hierfür nicht.', 'ab56f1',[68],COMMON)
S(13,'HH','hold','Der Originalanker verlangt die Beschreibung kathodischen Schutzes. Dafür ist Redoxwissen sachlich sinnvoll, aber der Anker belegt nicht die komplette aktuelle Vorleistung zum Aufstellen saurer und neutraler wässriger Teilgleichungen. Der weitergehende aktuelle Profilumfang darf nicht allein aus diesem Schutz-Operator abgeleitet werden.', '4f452d',[32],'Studienstufe: gemeinsamer Bereich')
S(13,'MV','hold','Verzinnter/verzinkter Stahl wird im gemeinsamen Original chemisch beschrieben. Der genaue aktuelle Profilumfang umfasst darüber hinaus saure und neutrale Bilanzierungen; diese ganze Vorleistung folgt nicht notwendig aus dem dortigen konkreten Stahl-Schutzauftrag. Der Kurs stimmt, die volle Operationsdeckung ist offen.', 'dcc123',[32],'Qualifikationsphase gemeinsamer Teil, gedruckte S.28')
S(13,'RP','hold','Das Original ordnet Korrosion und aktiven/passiven Schutz dem Fundamentum für Grund- und Leistungsfach zu; die extrahierte LK-Markierung ist damit nicht zuverlässig. Trotzdem belegt die bloße Schutz-Themenzeile die ganze aktuelle Vorleistung zu sauren und neutralen Redoxgleichungen nicht. Der Kursfehler ist geklärt, die Operationslücke bleibt.', '8d701a',[42],'MSS Grund- und Leistungsfach/Fundamentum')
S(13,'SL','hold','Die detaillierte Saarland-GK-Korrosionsschutzzelle besitzt im Paket keinen passenden oberen Primärpartner. Es fehlen die Originalseite und ihre Einordnung in GK/LK sowie der Nachweis, dass die vollständige aktuelle Redox-Bilanzierung tatsächlich verlangt wird.')
S(13,'ST','hold','Die Originalseiten belegen Wasserstoffkorrosion in gAN und eAN; die GK-Alternative ist also vorhanden. Die volle aktuelle Vorleistung umfasst zusätzlich neutrale/sauerstoffbezogene Bilanzierung. Aus Wasserstoffkorrosion allein folgt diese ganze Kompetenz nicht; der eAN-Anker darf die GK-Reichweite nicht erweitern.', 'fcdbb0',[42,51],'gAN und eAN: Wasserstoffkorrosion',{'ST':['anchor-3ecc09ad372c4f1b1e3a','anchor-08e5fbdfb283d6767b5e']})
S(13,'TH','approve','Die gemeinsame linke Originalspalte fordert ausdrücklich Säure- und Sauerstoffkorrosion zu erklären und Reaktionsgleichungen zu formulieren. Dafür braucht das vollständige aktuelle Profil die vorgelagerte Bilanzierung in saurem bzw. neutralem Milieu. Der nur rechts für eA stehende Eisen-Nachweisversuch wird nicht auf gA erweitert.', 'f89768',[54],COMMON,{'TH':['anchor-22a228ab4ed18bec3140']})

S(17,'NI','hold','Der ausgewählte Anker behandelt einen geerbten Kohlenwasserstoff-Kontext, keinen konkreten FCKW/HFKW-Auftrag zum kritischen Prüfen fremder Quellen. Unter den vorhandenen Alternativen ist für diesen Endpunkt kein original belegter passender Quellenkritik-Operator mit voller Kursbreite ausgewiesen. Erforderlich ist der konkrete Halogenkohlenwasserstoff-Recherche-/Kritikauftrag.')
S(17,'SH','hold','Die geerbte Organikquelle belegt nicht den aktuellen Auftrag, Aussagen zu FCKW/HFKW quellenkritisch zu vergleichen. Allgemeine Kommunikationskompetenz ersetzt keinen passenden ursprünglichen Halogenkohlenwasserstoff-Operator. Es fehlt eine genaue gemeinsame Kursstelle, an der diese kritische Recherche erworben werden soll.')
S(17,'HH','hold','Der gewählte Organikanker nennt keinen FCKW/HFKW-Quellenvergleich. Ohne tatsächlichen Originalauftrag zur Recherche und Prüfung solcher Aussagen lässt sich die ganze Quellenkritik-Vorleistung nicht als Erwerbsstütze dieses Ankers freigeben.')
S(17,'MV','hold','Der Stoffklassenanker ist keine originale Forderung, Halogenkohlenwasserstoff-Quellen nach Autorintention, Aktualität und Belastbarkeit zu prüfen. Genau dieser Operator und sein ursprünglicher Kurskontext fehlen für den angebotenen Ersatz.')
S(17,'RP','hold','Der geerbte Fachinhalt liefert keinen konkreten FCKW/HFKW-Rechercheauftrag mit Quellenkritik. Die aktuelle wissenschaftlich plausible Informationsprüfung darf nicht als ursprünglicher Operator der Quelle ausgegeben werden. Benötigt wird eine passende Originalklausel einschließlich Grund-/Leistungsfachzuordnung.')
S(17,'SL','hold','Eine Alternative zum Halogenalkan-Verbot existiert für EP NW; daraus folgt weder der volle aktuelle kritische Rechercheauftrag noch seine Geltung für den sprachlichen Zweig. Für die SPR-Alternative fehlt zudem der exakte Primärpartner. Fachinhalt, Quellenkritik und Zweigbreite sind getrennt nachzuweisen.')
S(17,'ST','hold','Die erreichbaren Kohlenwasserstoffzellen tragen keinen nachgewiesenen ursprünglichen FCKW/HFKW-Quellenkritikauftrag. Der aktuelle umfassende Quellenvergleich kann nicht aus einer geerbten Stoffklassen- oder Bewertungsthematik allein zur Pflichtvorleistung werden.')
S(17,'TH','hold','Der geerbte Struktur-/Reaktionsanker belegt keinen FCKW/HFKW-Auftrag zur Prüfung von Quellenintention und Evidenz. Es fehlt eine konkrete gemeinsame Originalklausel mit dieser Tätigkeit; reine Existenz einer Organikquelle ist kein Ersatz.')
S(22,'NI','approve','Der Originalauftrag leitet aus der Gefährlichkeit von Oxidationsprodukten begründete Handlungsoptionen ab. Das aktuelle Profil muss Optionen mit Kriterien gewichten; dazu werden tragfähige Pro-/Contra-Argumente aufgebaut und gegen Gegenargumente geprüft. Der fachsprachliche Unterschied im mechanisch gewählten Anker genügt hierfür nicht; der Handlungsanker ist die passende Alternative.', 'bd082d',[14],COMMON,{'NI':['anchor-25eeabc296559ec4918b']})
S(22,'SH','approve','Die Original-Prozesskompetenzen verlangen Kriterienbildung, begründete Entscheidungen und das Ableiten von Handlungsmöglichkeiten. Das aktuelle Bewerten braucht dafür die eigene gewichtete Pro-/Contra-Argumentation, nicht nur das Wiedergeben eines Standpunkts. Der ursprüngliche gemeinsame Sek-I-Prozessbereich trägt diese Erwerbsstütze.', 'ab56f1',[19],'Sekundarstufe I, allgemeine Bewertungskompetenz',{'SH':['anchor-262886dc9446479c979b']})
S(22,'HH','hold','Das ausgewählte Brennstoffzellen-Funktionsprinzip und die vorhandene allgemeine Argumentationsalternative fordern keine kriteriengeleitete Wahl zwischen Handlungsoptionen. Für die volle aktuelle eigene Pro-/Contra-Abwägung fehlt ein tatsächlich passender Original-Bewertungsauftrag.', '4f452d',[33],'Studienstufe, Brennstoffzellen-Funktionsprinzip')
S(22,'MV','approve','Das Original verlangt ausdrücklich, gesundheitliche, persönliche und gesellschaftliche Folgen von Ethanolmissbrauch zu bewerten. Das aktuelle Profil leitet im selben Bewertungstyp Handlungsoptionen nach mehreren Kriterien ab. Dazu sind begründete und gewichtete Argumente erforderlich; reine Stoffeigenschaften würden nicht genügen.', 'eb8c6e',[35],'Klasse 10, gemeinsamer Sek-I-Standard, gedruckte S.31')
S(22,'RP','approve','Der Originaltext fordert eine Bewertung von Treibstoffen aus Ressourcen-, Umwelt- und Nachhaltigkeitsperspektiven. Das aktuelle Entscheidungsprofil muss diese konkurrierenden Kriterien argumentativ gewichten. Damit ist die eigene Pro-/Contra-Begründung echte Vorleistung für diesen Quellauftrag.', '307f5d',[72],'Sekundarstufe I, Themenfeld Treibstoffe, gedruckte S.70')
S(22,'SL','hold','Der gewählte Saarland-Anker verlangt die Durchführung von Salzbildungsversuchen und enthält Extraktionsreste; er fordert keine kriteriengeleitete Handlungsentscheidung. Das zugehörige Klasse-9-Original ist unter den exakten Partnern nicht vorhanden. Ein passender Bewertungsoperator bleibt unbelegt.')
S(22,'ST','approve','Die Originalseite fordert eine ökologische, ökonomische und gesellschaftliche Bewertung von Erdgas, Erdöl und Biogas im Energiewende-Kontext. Die aktuelle Optionenabwägung braucht dafür selbst aufgebaute, gewichtete Argumente. Der mechanisch gewählte zwischenmolekulare-Wirkungen-Anker wird durch den passenden Bewertungsanker ersetzt.', 'fcdbb0',[31],'Schuljahrgang 9, allgemeiner Standard',{'ST':['anchor-cd3176d530f13cecccc4']})
S(22,'TH','approve','Die gemeinsame Originalspalte fordert die Bewertung von Recyclingverfahren aus ökonomischer und ökologischer Sicht. Diese kriteriengeleitete Handlungsentscheidung benötigt im aktuellen Profil begründete Pro-/Contra-Gewichtung. Die nur eA zugeordnete PET-Kreislaufdarstellung ist hierfür nicht der Beleg.', 'f89768',[58],COMMON,{'TH':['anchor-47d769ccf31240fb7f09']})
S(23,'BB BE','hold','Die Originalstelle nennt Bedeutung und Funktion der Proteine. Sie verlangt keinen Vergleich tierischer/pflanzlicher Proteinquellen nach Nachhaltigkeit und Quellenintention. Gerade die aktuelle nachhaltige Abwägung kann deshalb nicht aus dieser Funktionsüberschrift als Quellenersatz bestätigt werden.', '2fa91c',[27],'Qualifikationsphase Proteine; Kursbreite ersetzt keinen Bewertungsoperator')
S(27,'SH','hold','Der ausgewählte Stoff-Teilchen-Auftrag erklärt den Aufbau von Stoffgemischen. Er verlangt keine quantitative Gehaltsbestimmung samt Prüfung von Messunsicherheit. Es fehlt eine konkrete originale quantitative Analysenaufgabe; Teilchenmodellwissen allein begründet diese Datenkritik-Vorleistung nicht.', 'ab56f1',[20],'Sekundarstufe I, Stoff-Teilchen-Konzept')
S(27,'HH','hold','Die Originalzelle erklärt Schmelzbereiche von Fetten. Sie ist kein quantitativer Reinstoffgehaltsauftrag mit Messfehlerprüfung. Ein passender ursprünglicher Analyseoperator, der die aktuelle Datenkritik benötigt, fehlt.', '4f452d',[25],'Studienstufe, Fette')
S(27,'MV','hold','Die Originalstelle unterscheidet gesättigte/ungesättigte Lösungen und Löslichkeit im LK. Sie fordert nicht die aktuelle quantitative Gehaltsbestimmung mit belastbarer Messwertauswertung und trägt außerdem keine GK-Breite. Ein geeigneter gemeinsamer Analysenbeleg fehlt.', 'dcc123',[28],'Qualifikationsphase: ausgewählte Löslichkeitsvertiefung LK')
S(27,'RP','approve','Die Originalseite verlangt die quantitative Erfassung von Stoffen und die Verfahrenswahl anhand von Messgenauigkeit und Nachweisgrenze. Das aktuelle Profil muss einen belastbaren Gehalt aus Daten und deren Grenzen bestimmen. Diese Entscheidung benötigt genau die vorgelagerte Beurteilung der Messwertgültigkeit.', '307f5d',[84],'Sekundarstufe I, quantitative Analytik, gedruckte S.82')
S(27,'SL','hold','Die Klasse-8-Quelle unterscheidet homogene und heterogene Gemische. Das ist keine quantitative Bestimmung des Reinstoffgehalts. Eine konkrete ursprüngliche Quantifizierung mit zu prüfender Messqualität fehlt; die Mischungsbezeichnung darf sie nicht ersetzen.')
S(27,'ST','hold','Der ausgewählte eAN-Auftrag berechnet Sättigungskonzentrationen aus einem Löslichkeitsprodukt. Das ist keine experimentelle Reinstoffgehaltsbestimmung und fordert nicht die aktuelle volle Messwertkritik. Zusätzlich trägt der LK-Beleg keine allgemeine GK-Zeile.')
S(27,'TH','hold','Der ausgewählte Katalyse-Definitionsauftrag ist weder quantitative Gemischanalyse noch Prüfung der Verlässlichkeit solcher Gehaltsdaten. Ohne passenden Original-Analyseoperator ist diese Quelle für die angebotene Erwerbsstütze ungeeignet.')
S(28,'BW','hold','Das Original fordert Gefahrenpiktogramme zu nennen und Gefahrenpotenziale abzuleiten. Der volle aktuelle Zielumfang beurteilt zusätzlich Exposition und begründet Risikominderung. Das bloße Erkennen von Gefahrkennzeichen verlangt diese ganze vorgelagerte Schutzmaßnahmenkompetenz noch nicht.', '3ae66c',[15],'Klassen 8/9/10, gedruckte S.13')
S(28,'NI','approve','Die Originale verbinden die Beurteilung von Gefahren/Sicherheit mit daraus abgeleiteten Handlungsoptionen. Im aktuellen Risiko-Profil sind begründete Schutzmaßnahmen Teil der verlangten Risikoreduktion. Die Kenntnisse über Schutzbrille, Abzug und geeignete Maßnahmen sind deshalb ausführungsrelevant und nicht nur Hintergrund.', 'bd082d',[14,28],COMMON,{'NI':['anchor-115d869e701d8f743bcc','anchor-9f602210e36a7dbcac3f']})
S(28,'SH','hold','Der ausgewählte Originaloperator entwirft ein Untersuchungsdesign; die Sicherheitsalternative verlangt den sachgerechten Umgang mit Geräten. Beides belegt nicht vollständig den aktuellen Auftrag, Gefahrenpotenzial und Exposition zu beurteilen und Risiken begründet zu reduzieren. Eine konkrete passende Bewertungs-/Reduktionsklausel fehlt.', 'ab56f1',[18],'Sekundarstufe I, Erkenntnisgewinnung')
S(28,'HH','hold','Das Original fordert Sicherheits- und Umweltaspekte beim Experimentieren zu beachten. Das belegt regelgerechtes Verhalten, aber nicht die volle aktuelle Gefahren-/Expositionsbeurteilung mit begründeter Auswahl von Minderungsmaßnahmen. Diese Operationslücke bleibt trotz passendem Sicherheitsthema.', '415d17',[20,22],'Sekundarstufe I, allgemeine experimentelle Kompetenz')
S(28,'MV','hold','Die Originalseite nennt Umgang mit Chemikalien und Grundregeln im Fachraum. Das ist ein passender Sicherheitsrahmen, aber keine volle Beurteilung von Exposition und Maßnahmenwirksamkeit im aktuellen Risikoprofil. Ein solcher konkreter Bewertungsoperator fehlt.', 'eb8c6e',[17],'Klasse 8, gedruckte S.13')
S(28,'RP','approve','Das Originalthemenfeld fordert die Analyse des Nutzens und der Risiken von Gefahrstoffen und ihrer Handhabung. Die aktuelle begründete Reduktion des Risikos setzt die vorgelagerten Schutzmaßnahmen als konkrete Optionen voraus. Verwendet wird die passende Nutzen-Risiko-Alternative statt der alleinigen Recherchezeile.', '307f5d',[86],'Sekundarstufe I, Gefahrstoffe, gedruckte S.84',{'RP':['anchor-df9fe69010658e431190']})
S(28,'SL','hold','Das Original verlangt das Nennen und Beachten von Regeln sowie das Nennen von Green-Chemistry-Prinzipien. Es verlangt keine vollständige aktuelle Gefahren-/Expositionsbeurteilung. Aus einem Nennoperator darf die weitergehende kriteriengeleitete Risikoreduktion nicht als notwendige volle Vorleistung geschlossen werden.', '3e5d6f',[12],'Klasse 8, sicherer Anfangsunterricht')
S(28,'ST','hold','Der Löslichkeits-Untersuchungsanker und die Sicherheitsalternative für angeleitete Versuche verlangen keine eigene volle Gefahren-/Expositionsbeurteilung. Die reale Sicherheit bleibt erforderlich; der konkrete aktuelle Bewertungsumfang ist in diesen Originaloperatoren jedoch nicht nachgewiesen.', 'fcdbb0',[20],'Schuljahrgänge 7/8, angeleitete Experimente')
S(28,'TH','approve','Das Original verbindet das Einschätzen des Gefahrenpotenzials anhand der Kennzeichnung mit dem dazu passenden Einhalten von Sicherheitsbestimmungen. Das aktuelle Profil beurteilt das Risiko und reduziert es durch die passenden Schutzmaßnahmen. Die vorgelagerten Schutzkenntnisse sind für diese konkrete Auswahl erforderlich.', 'f89768',[19],'Klassen 7/8, Grundregeln im Fachraum')
S(33,'SH','approve','Das Medikamenten-Themenfeld fordert den zusammenhängenden Weg von Entwicklung über Herstellung zu Vermarktung. Das aktuelle Profil muss hierfür relevante Informationen aus Material entnehmen, begründet auswählen und für ein kohärentes Produkt zusammenführen. Die ausgewählte Informationskompetenz ist eine tatsächliche Arbeitshandlung dieses Auftrags.', 'ab56f1',[69,71],'Sekundarstufe II, optionales Themenfeld Medikamente, gemeinsame Spalte gA/eA',qualification='Offizielles optionales Themenfeld bleibt optional. Aufnahme in den breiteren SkillPilot-Zielumfang nach Eigentümerentscheidung ist keine offizielle Pflicht und kein Nachweis einer individuellen Themenwahl.')
S(34,'BB','approve','Das Originalthemenfeld verbindet Erdöl/Kraftstoffe mit alternativen Energieträgern und nachhaltigem Wirtschaften. Das aktuelle Profil recherchiert und vergleicht fossile und nachwachsende Rohstoffe anhand belastbarer Angaben. Dazu ist die vorgelagerte Auswahl und Auswertung fachlich relevanter Informationen erforderlich.', '2fa91c',[17,23],EP,qualification='Wahlpflicht-Themenfeld; keine allgemeine offizielle Themenpflicht oder individuelle Wahlbehauptung.')
S(34,'BE','hold','Der mechanisch gewählte Terpen-/Isoprenanker behandelt Bau, Einteilung und Eigenschaften von Naturstoffen. Er verlangt keinen Nachhaltigkeitsvergleich fossiler und nachwachsender Rohstoffe. Ein passender Originalvergleich samt Informationsauftrag ist für diesen Berliner Endpunkt nicht ausgewiesen.', '2fa91c',[21],'Einführungsphase, Grundlagen Organik')
S(34,'NI','approve','Der Originaloperator fordert ausdrücklich den Vergleich fossiler und nachwachsender Rohstoffe im Sinne der Nachhaltigkeit. Die aktuellen Aufgaben verlangen dafür eigene belastbare Stoff- und Folgeninformationen. Deren fachgerechte Beschaffung und Auswahl ist somit notwendig.', 'bd082d',[13],COMMON)
S(34,'HH','hold','Die Sek-I-Quelle nennt homologe Reihen und Ethanol als Rauschmittel. Ein vergleichender Recherche-/Nachhaltigkeitsauftrag zu fossilen und nachwachsenden Rohstoffen ist dort nicht belegt. Die stoffliche Nachbarschaft reicht für die volle aktuelle Informationskompetenz nicht.', '415d17',[22],'Sekundarstufe I, organische Stoffe')
S(34,'MV','hold','Der Alkananker und seine Alternativen zu Folgen fossiler Rohstoffnutzung belegen keinen vollständigen ursprünglichen Vergleich mit nachwachsenden Rohstoffen. Die aktuelle nachhaltige Gegenüberstellung einschließlich Informationsprüfung darf daraus nicht pauschal abgeleitet werden.', 'eb8c6e',[32],'Klasse 10, Organische Chemie, gedruckte S.28')
S(34,'ST','approve','Die originale Bewertungsaufgabe stellt Erdgas, Erdöl und Biogas im Energiewende-Kontext unter ökologische, ökonomische und gesellschaftliche Gesichtspunkte. Das aktuelle Profil muss für genau diese Gegenüberstellung Informationen auswählen und auswerten; bloßes Strukturwissen genügt nicht.', 'fcdbb0',[31],'Schuljahrgang 9, gemeinsamer Standard')
S(34,'TH','hold','Der ausgewählte Schülerexperiment-Operator untersucht Brennbarkeit und Löslichkeit von Alkanen. Er fordert weder einen Rohstoffvergleich noch eine nachhaltige Recherchebewertung. Für diese andere Tätigkeit fehlt ein genauer Originalnachweis; ein vorhandener Stoffklassenpfad ersetzt ihn nicht.', 'f89768',[27],'Klassen 9/10, Kohlenwasserstoffe')
S(35,'RP','hold','Der ausgewählte medizinhistorische Auftrag und die Qualitätskontrollalternative tragen nicht den vollständigen aktuellen Rechercheauftrag zu Chemie und Konsum von Schmerzmitteln anhand überprüfter aktueller Quellen. Der konkret notwendige Informationsoperator mit entsprechender Stoff-/Bewertungsbreite ist im angebotenen Originalkontext nicht belegt.', '8d701a',[38],'MSS, Analytik; medizinhistorischer bzw. Qualitätskontrollkontext')
S(35,'SL','hold','Der verfügbare Anker zur Erdölübersicht ist kein ursprünglicher Schmerzmittel-Rechercheauftrag. Es fehlen eine passende aktuelle Arzneimittel-Klausel samt Zweig-/Kurskontext und ihr exakter Primärpartner; allgemeine Informationskompetenz allein ersetzt sie nicht.')
S(37,'NI','approve','Der Originalauftrag erklärt die Funktionsweise von Opferanoden. Im aktuellen Schutzprofil werden aktive und passive Schutzmaßnahmen gerade aus den jeweils unterbundenen Korrosionsschritten beurteilt. Die vorgelagerte Korrosionsreaktion ist daher für die fachliche Begründung der Schutzwirkung erforderlich.', 'bd082d',[26],COMMON,{'NI':['anchor-379c6bfd8f9650e63682']})
S(41,'NI','approve','Das Original erläutert das Prinzip der Elektrolyse im gemeinsamen Kursbereich. Das aktuelle vertiefte Profil vergleicht Elektrolyse und galvanische Zelle anhand der umgekehrten Elektrodenprozesse. Dafür ist die vorgelagerte qualitative Zuordnung von Stoffumsatz, Elektroden und Energiezufuhr erforderlich; die LK-Faraday-Erweiterung wird nicht verwendet.', 'bd082d',[26],COMMON,{'NI':['anchor-8af6c96316d401252b6c']})
S(41,'SH','approve','Die gemeinsame Originalspalte verlangt Elektrolyse und die Energieumwandlung im Vergleich mit galvanischen Zellen. Die aktuellen Vergleichsaufgaben bauen zwingend auf den grundlegenden Elektrodenreaktionen und der erzwungenen Richtung auf. Die quantitative LK-Erweiterung wird dabei nicht auf gA ausgeweitet.', 'ab56f1',[67,68],COMMON)
S(41,'HH','approve','Das Original verlangt im gemeinsamen Bereich die Beschreibung des Elektrolyseprinzips und den Vergleich zur galvanischen Zelle. Das aktuelle Profil muss dafür bereits Anode/Kathode, Stoffumsatz und Energiezufuhr der einfachen Salzelektrolyse verstehen. Faraday steht im Zusatzbereich und ist für diese Zustimmung kein Grundkursbeleg.', '4f452d',[32],'Studienstufe, gemeinsamer Bereich',{'HH':['anchor-0e4e5e88c59634990462']})
S(41,'MV','approve','Die Originalseite nennt die wässrige Elektrolyse mit Elektrodenreaktionen und verlangt den Vergleich der Elektrolysezelle mit galvanischer Zelle im gemeinsamen Teil. Diese konkrete Gegenüberstellung benötigt im aktuellen Profil das grundlegende Verständnis der erzwungenen Salz-Elektrolyse. Der folgende zusätzliche LK-Teil wird nicht verallgemeinert.', 'dcc123',[34],'Qualifikationsphase, gemeinsamer Teil, gedruckte S.30',{'MV':['anchor-78f14801212560261023']})
S(41,'RP','approve','Die Originalseite führt Elektrolyse und Elektrodenprozesse im Fundamentum für Grund- und Leistungsfach. Die extrahierte LK-Markierung beschreibt die tatsächliche Spaltenzuordnung nicht zutreffend. Das aktuelle Vergleichsprofil braucht die grundlegenden Stoff- und Ladungsprozesse der Elektrolyse; Faraday bleibt LK-Additum.', '8d701a',[42],'MSS Grund- und Leistungsfach/Fundamentum',{'RP':['anchor-9765cc30eb74352653df']},'Kursinterpretation nach tatsächlicher Originalspalte, keine automatische LK-zu-GK-Vererbung; Rohmetadaten unverändert.')
S(41,'SL','hold','Für den konkreten oberen Saarland-Elektrolyseanker fehlt im exakten Paket das zugehörige GK-/LK-Original. Die gelesenen Klasse-8- und EP-NW-Partner schließen diese Lücke nicht. Physikalische Notwendigkeit der einfachen Elektrolyse ersetzt den fehlenden Kurs-/Programmbeleg nicht.')
S(41,'ST','approve','Die Originaltexte für gAN und eAN verlangen Elektrolyse als erzwungene Redoxreaktion zu erklären und mit galvanischen Elementen zu vergleichen. Genau für diese Richtungs- und Funktionsgegenüberstellung braucht das aktuelle Profil das grundlegende Elektrolysewissen. Beide Kurse werden gesondert gebunden.', 'fcdbb0',[42,51],'11/12 gAN und eAN',{'ST':['anchor-4de7ebdfc54b99930832','anchor-4c87edc207dc4e6fc652']})
S(41,'TH','approve','Die gemeinsame linke Originalspalte behandelt die erzwungene Redoxreaktion, ihren Vergleich mit galvanischen Zellen und die Salzelektrolyse. Damit wird die konkrete qualitative Elektrolyse-Vorleistung des aktuellen Vergleichsprofils benötigt. Der mechanisch gewählte Faraday-Zusatz rechts ist kein GK-Beleg.', 'f89768',[54],COMMON,{'TH':['anchor-08af6220ce8f348ae5d9']})
S(44,'NI','approve','Die Originalseite verknüpft die experimentelle Reaktionsenthalpie mit dem Satz von Hess. Das aktuelle Profil muss Systemgrenze, Wärme/Arbeit und Vorzeichen ausdrücklich bestimmen, bevor es Kalorimeterdaten und Hess-Wege kombiniert. Die vorgelagerte Energieerhaltungs-/Systemkompetenz ist deshalb wirklich erforderlich.', 'bd082d',[17],COMMON,{'NI':['anchor-4cd92af521112709aae9','anchor-4964057c38d58cd29624']})
S(59,'BB BE','hold','Die Originalstelle zählt Brennstoffzellen als Typ elektrochemischer Spannungsquellen auf. Sie verlangt nicht die volle aktuelle Beurteilung saurer und alkalischer H2/O2-Brennstoffzellen einschließlich Quellenprüfung. Der Typname allein macht die ganze aktuelle vorgelagerte Brennstoffzellenkompetenz nicht zur original belegten Erwerbsbedingung.', '2fa91c',[53],'Qualifikationsphase, gemeinsamer Bereich')
S(67,'BW','approve','Der Originaloperator fordert Reaktionsgleichungen ausdrücklich in Formelschreibweise. Das aktuelle Gleichungsprofil muss richtige Formelindizes erhalten und Koeffizienten ändern. Dazu ist das vorgelagerte sichere Lesen von Elementsymbolen, Indizes und Stoffformeln eine echte fachliche Voraussetzung.', '3ae66c',[23],'Klassen 9/10/11, gemeinsamer Sek-I-Standard')
S(67,'SH','hold','Die Originalseite erlaubt ausdrücklich Wortschemata ODER Formelschreibweise. Der mechanisch gewählte Luftbestandteile-Anker fordert ebenfalls keine Formelgleichung. Die volle aktuelle Symbol-/Formelkompetenz kann nicht allein aus diesem offenen Darstellungsoperator zur notwendigen Quellen-Vorleistung werden.', 'ab56f1',[23],'Sekundarstufe I, Darstellungsalternative Wort-/Formelschema')
S(67,'HH','approve','Das Original verlangt das Aufstellen von Reaktionsgleichungen mit Oxidationszahlen im gemeinsamen Studienstufenbereich. Das aktuelle Profil setzt unveränderte Formelindizes und richtige Stoffformeln ein; deren Bedeutung muss dafür vor dem Bilanzieren verstanden sein.', '4f452d',[31],'Studienstufe, gemeinsamer Bereich')
S(67,'MV','approve','Die Originalseite fordert die Darstellung von Säuren aus Nichtmetalloxid und Wasser samt Reaktionsgleichungen. Das aktuelle Gleichungsprofil benötigt hierfür ausdrücklich Stoffformeln und deren Indizes. Das ist notwendige chemische Zeichensprache, nicht nur ein nützliches Zusatzwissen.', 'eb8c6e',[28],'Klasse 9, Säuren, gedruckte S.24')
S(67,'RP','approve','Das Original beschreibt Neutralisationsreaktionen ausdrücklich durch Reaktionsgleichungen und benennt Oxonium-/Hydroxidteilchen. Das aktuelle Profil kann die Stoff- und Atomzahlbilanz nur bei unveränderten, richtig gelesenen Formeln ausführen. Die Formel-Vorleistung ist deshalb für diesen Operator erforderlich.', '307f5d',[78],'Sekundarstufe I, gedruckte S.76')
S(67,'SL','hold','Die Originalseite bestätigt die HCl/NaHCO3-Neutralisationsgleichung für EP NW. Sie belegt nicht automatisch dieselbe originale Anforderung für den sprachlichen Zweig, der in der breiten Landeszeile nicht gesondert begrenzt ist. Ein passender SPR-Originalnachweis oder eine zweiggenaue Ersatzzeile fehlt.', '26da6e',[11],'Einführungsphase, ausschließlich naturwissenschaftlicher Zweig')
S(67,'ST','approve','Die Originalseite verlangt die erläuterte Bildung von Ammoniumionen unter Nutzung von Lewis-Formeln und verknüpft qualitative mit quantitativen Betrachtungen. Das aktuelle einfache Gleichungsprofil braucht dafür die Bedeutung von Symbol, Index und Ladung vor der Atombilanzierung. Diese Formelsprache wird konkret benutzt.', 'fcdbb0',[34],'Schuljahrgang 10 / Einführungsphase, gemeinsamer Standard')
S(67,'TH','approve','Die passende Originalalternative fordert Wort- UND Formelgleichungen für Oxidationsreaktionen. Für deren current P-Ausgleich mit unveränderten Indizes ist die Symbol-/Formelkompetenz erforderlich. Die mechanisch gewählte bloße Strukturformel-Darstellung wird hierfür nicht als Reaktionsoperator umgedeutet.', 'f89768',[20],'Klassen 7/8, gemeinsamer Standard',{'TH':['anchor-5e00318ed89c10dff5f2']})
S(68,'BB BE','approve','Im ursprünglichen Säure-Base-Themenfeld werden Protonenübergänge auf Teilchenebene modelliert. Das aktuelle Profil schreibt korrespondierende Paare als konkrete Formeln und muss dabei H, Ladungen und Indizes korrekt verändern. Die vorgelagerte Formelsprache ist gerade für diese Handlung notwendig.', '2fa91c',[20],'Einführungsphase, Themenfeld Säuren/Basen; ohne GK/LK-Differenzierung',qualification='Einführungsphasen-Themenangebot ist keine Behauptung einer individuellen Themenwahl.')
S(68,'NW','approve','Die getrennt gelesenen GK-/LK-Originalabschnitte fordern die Deutung von Säure-Base-Reaktionen nach Brønsted auf Teilchenebene. Das aktuelle Profil formuliert dabei konjugierte Paare durch Protonenabgabe/-aufnahme und verlangt richtige Stoffformeln und Ladungen. Dafür wird Symbol-/Formelverständnis tatsächlich gebraucht; der PSE-Anker allein wäre zu unspezifisch.', '24af8d',[39,47],'Qualifikationsphase: GK S.39 und LK S.47',{'NW':['anchor-9761cbf34d8fc1dc5e92','anchor-3b8b48a791ddb7981f74']})
S(69,'HE','hold','Das Original nennt die Fehling-Probe mit Aldosen als Inhalt. Für den hier angebotenen Ersatz einer vollständigen praktischen Durchführungs-Vorleistung reicht die Nennung der Probe nicht als Nachweis, dass im konkreten Originalauftrag tatsächliche Durchführung statt Erklärung/Auswertung verlangt wird. Der enge Originaloperator muss ergänzt werden.', '346125',[42],'Q2.1 gemeinsamer Grund-/Leistungskurs; benannter Inhalt, kein hier nachgewiesener Durchführungsoperator')
S(69,'SH','hold','Das Original nennt Vorkommen, Eigenschaften und Nachweis von Glucose/Fructose. Die nötige fachliche Nachweiskompetenz ist damit vorhanden, der konkrete Tätigkeitsmodus Durchführung versus Beschreibung/Auswertung ist für die volle praktische Vorleistung aber nicht aufgelöst. Aus dem Substantiv Nachweis wird keine reale Durchführungspflicht abgeleitet.', 'ab56f1',[64],COMMON)
S(69,'RP','hold','Das tatsächliche Original führt die Unterscheidung reduzierender/nichtreduzierender Kohlenhydrate im Wahlpflicht-Fundamentum beider Kurse, nicht nur LK. Es fordert dort aber keine reale Nachweisdurchführung. Das vollständige angeleitete praktische Experimentieren ist für die bloße Unterscheidung nicht als notwendige Originalvorleistung belegt.', '8d701a',[60],'Wahlpflicht Makromoleküle I; Grund-/Leistungsfach-Fundamentum')
S(69,'SL','hold','Die Klasse-8-Zuckerwasser-Teilchenmodellquelle ist kein Auftrag zur Nachweisreaktion reduzierender Kohlenhydrate. Weder der chemische Nachweis noch tatsächliche Durchführung und passende spätere Kursstufe werden durch diese Alltagsmodellierung belegt.')
S(69,'TH','hold','Die tatsächlichen Originalspalten ordnen den Kohlenhydratbereich einschließlich der Zucker-Nachweise dem zusätzlichen eA-Bereich zu. Die gemeinsame GK/LK-Rohmarkierung darf daraus keine gA-Pflicht machen. Ein entsprechender gA-Durchführungsbeleg oder eine kursgenaue Begrenzung fehlt.', 'f89768',[57,58],'Qualifikationsphase: Kohlenhydrate im zusätzlichen erhöhten Bereich; Rohmarkierung zu breit')
S(70,'BW','hold','Das Original fordert Ninhydrin- und Biuret-Nachweise tatsächlich durchzuführen, jedoch im Leistungsfach. Die Basisfachalternative nennt zwar Proteinuntersuchungen mit Biuret, aber nicht den vollständigen aktuellen Aminocarbonsäuren- und Peptidumfang mit Ninhydrin. Diese gemeinsame Paarzeile darf nicht über die LK-Quelle geschlossen werden.', '3ae66c',[38],'Klassen 11/12 Leistungsfach; Basisfachalternative deckt nicht den gesamten aktuellen Umfang',{'BW':['anchor-659547ea7fa2d0a8657a','anchor-30bcd3e0d500dea3ee51']})
S(70,'BY','approve','Die originären LehrplanPLUS-Seiten für C13 grundlegend und erhöht verlangen unabhängig voneinander die tatsächliche Durchführung von Nachweisreaktionen für Aminocarbonsäuren und Peptide. Für diese Ausführung braucht das aktuelle Profil angeleitetes sachgerechtes Experimentieren. Die aktuelle GA-Klausel wurde neu direkt gelesen; Zustimmung beruht nicht auf einer Übertragung vom EA-Titel.', 'BY-ORIGINALS',[],'C13 4.1, grundlegend UND erhöht; beide Originale getrennt gelesen',qualification='Die Rohstelle C13-GA.4.5 ist als Locator unzutreffend; tatsächliche originale Klausel ist C13 4.1. Nur wissenschaftliche Erwerbsstütze für vorgeschlagene BY-Views, keine Aktivierung.')
S(71,'NI','approve','Der gemeinsame Originaltext verlangt ausdrücklich die Durchführung der Iod-Stärke-Reaktion. Das aktuelle Lebensmittel-Nachweisprofil fordert dabei reale sachgerechte Handhabung, Durchführung und Auswertung. Für diese praktische Tätigkeit ist die vorgelagerte angeleitete Experimentierkompetenz notwendig; die zusätzliche LK-Biuret-Probe wird nicht auf den GK erweitert.', 'bd082d',[32],COMMON)
S(74,'BB BE','hold','Das Original zählt Sekundärelemente als Typ elektrochemischer Quellen auf. Das impliziert zwar die Umkehrbarkeit von Lade-/Entladeprozessen, belegt aber noch nicht den vollen aktuellen quellenkritischen Recherche- und Bewertungsauftrag zu Sekundärzellen. Eine entsprechende ursprüngliche Operationsklausel fehlt.', '2fa91c',[53],'Qualifikationsphase, gemeinsamer Bereich')
S(79,'BB BE','approve','Das Originalthemenfeld behandelt Stofftrennung und Reinstoffisolierung gerade durch Nutzung unterschiedlicher Stoffeigenschaften. Die aktuelle Trennentscheidung begründet ihre Verfahrenswahl aus diesen Eigenschaften. Das vorgelagerte geordnete Beschreiben und Zuordnen von Eigenschaften ist dafür erforderlich.', '2fa91c',[17,25],EP,qualification='Wahlpflicht-Themenfeld bleibt als solches bezeichnet; kein Nachweis individueller Auswahl oder tatsächlicher praktischer Leistung.')

if __name__=='__main__':
    required=json.loads((OUT/'POTENTIAL-SOURCE-REVIEW.remaining-neutral.json').read_text())
    expected={(x['groupIndex'],x['docket']['jurisdiction']) for x in required}
    assert set(SOURCE)==expected,{'missing':sorted(expected-set(SOURCE)),'extra':sorted(set(SOURCE)-expected)}
    rows=[]
    for x in required:
        i=x['groupIndex'];d=x['docket'];r=SOURCE[(i,d['jurisdiction'])].copy()
        aids=r['witnessAnchorIds'] or [d['endpointAnchorId']]
        endpoint=ANCHORS[d['endpointAnchorId']]['endpointGoalId']
        assert all(ANCHORS[a]['endpointGoalId']==endpoint for a in aids),(i,d['jurisdiction'],aids,endpoint)
        r.update(pairKey=x['key'],groupIndex=i,reviewGroupId=GROUPS[i]['reviewGroupId'],
                 prerequisiteGoalId=d['goalId'],jurisdiction=d['jurisdiction'],
                 originalMechanicallySelectedAnchorId=d['endpointAnchorId'],witnessAnchorIds=aids)
        rows.append(r)
    dest=OUT/'FIRST-SOURCE-READING-DECISIONS.frozen.json'
    with dest.open('x') as f:json.dump({'atUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'reviewer':'independent-scientific-B','semantics':'First original-source findings for 109 unflagged pairs whose selected physical chain passed. No source row, canonical goal, registry, gate or view is changed.',
        'rows':rows},f,ensure_ascii=False,indent=2);f.write('\n')
    print('FROZEN',len(rows),dict(collections.Counter(r['decision'] for r in rows)))
